from typing import Any

import pytest

GOOD_DIFF = (
    b"C /opt\nC /opt/maskgw\nA /opt/maskgw/oracle9-installed.json\n"
    b"A /opt/maskgw/venv/lib/python3.11/site-packages/maskgw/__init__.py\n"
