@pytest.fixture
def host() -> Any:
    path = Path(__file__).resolve().parents[1] / "docs/poc/oracle9_offline_prepare.py"
    spec = importlib.util.spec_from_file_location("_offline_host_under_test", path)
    assert spec is not None and spec.loader is not None
